// Illustrated Edison assets. Embedded for offline/file:// play.
(function(root){
 const S=root.TrainingSprites={};
 S.tire=new Image();S.tire.src='data:image/png;base64,';
 S.expressions=new Image();S.expressions.src='data:image/png;base64,';
 S.tireStart=new Image();S.tireStart.src='data:image/png;base64,';
 const faces=[];
 S.expressions.onload=()=>{for(let i=0;i<3;i++){const c=document.createElement('canvas');c.width=S.expressions.width/3;c.height=S.expressions.height;c.getContext('2d').drawImage(S.expressions,i*c.width,0,c.width,c.height,0,0,c.width,c.height);faces.push(c);}};
 S.face=i=>faces[i];
 S.drawTire=(c,frame,x,y,width,height)=>{const im=S.tire;if(!im.complete||!im.naturalWidth)return false;if(frame===0&&S.tireStart.naturalWidth){const start=S.tireStart,sh=start.height*.8125,dh=width*sh/start.width;c.drawImage(start,0,0,start.width,sh,x,y+height-dh,width,dh);return true;}const sw=im.width/4,sh=im.height/2;c.drawImage(im,(frame%4)*sw,Math.floor(frame/4)*sh,sw,sh,x,y,width,height);return true;};
})(window);
